function showForm(type, existing = {}, extras = {}) {
  const config=FORMS[type]; if(!config) return;
  const data={...existing,...extras}; pendingSubmit={type, id:data.id||null, original:data};
  $('#dialogTitle').textContent=data.id?`Edit ${config.title.toLowerCase()}`:config.title;
  $('#dialogEyebrow').textContent=config.eyebrow; $('#dialogSubmit').textContent=data.id?'Save changes':config.submit;
  $('#dialogFields').innerHTML=config.fields(data);
  const dialog=$('#entityDialog'); if(!dialog.open) dialog.showModal();
  const first=$('#dialogFields input:not([type=hidden]), #dialogFields select, #dialogFields textarea'); first?.focus({preventScroll:true});
}
function formValues(form) {
  const fd=new FormData(form), out={};
  for(const [key,value] of fd.entries()) { if(key.startsWith('milestone-')) continue; if(key==='tags') out.tags=String(value).split(',').map(x=>x.trim()).filter(Boolean).slice(0,40); else if(value==='') out[key]=''; else if(['plannedMinutes','actualMinutes','expectedQuestions','completedQuestions','correct','incorrect','skipped','targetHours','estimatedHours','estimatedMinutes','targetQuestions','examYear','timeMinutes','maxMarks','score','totalQuestions','unattempted','durationMinutes','rank','percentile','targetValue','availableHours','confidence'].includes(key)) out[key]=Number(value); else out[key]=String(value).trim(); }
  for(const input of $$('input[type=checkbox]',form)) out[input.name]=input.checked;
  return out;
}
function auditEntity(action,type,entity,detail='') { logEvent(action,type,entity?.id||null,detail||entity?.title||entity?.name||entity?.id||''); }
async function submitEntity(form) {
  if(!pendingSubmit) return;
  const {type,id:existingId,original}=pendingSubmit; const d=formValues(form); const now=new Date().toISOString();
  const listMap={task:'tasks',subject:'subjects',chapter:'chapters',topic:'topics',goal:'goals',block:'calendarEvents',module:'modules',note:'notes',revision:'revisions',test:'tests',calendar:'calendarEvents'};
  if(type==='attempt') {
    const moduleId=original.moduleId; const item={id:id('attempt'),moduleId,at:now,...d};
    if(!item.outcome) item.outcome='unresolved'; state.attempts.push(item); auditEntity('recorded-attempt','attempt',item,item.outcome); await persist('Question attempt recorded.'); $('#entityDialog').close(); pendingSubmit=null; render(); return;
  }
  const list=state[listMap[type]]; let item=existingId?find(list,existingId):null;
  if(type==='task'&&d.completedQuestions>0&&d.correct+d.incorrect>d.completedQuestions) { toast('Correct + incorrect answers cannot exceed completed questions.','error');return; }
  if(type==='test'&&d.score!==''&&d.maxMarks>0&&d.score>d.maxMarks) { toast('Score cannot exceed maximum marks.','error');return; }
  if(type==='topic'&&d.parentTopicId===existingId) { toast('A topic cannot be its own parent.','error');return; }
  const before=item?JSON.stringify(item):'';
  const previousPlannedDate=item?.plannedDate; const previousRevisionDate=item?.date; const previousTarget= item ? { targetValue:item.targetValue,horizon:item.horizon,unit:item.unit } : null;
  if(!item) { item={id:id(type),createdAt:now}; list.push(item); }
  Object.assign(item,d,{updatedAt:now});
  if(type==='task'&&existingId&&previousPlannedDate!==item.plannedDate){item.history=[...(item.history||[]),{at:now,action:'rescheduled',from:previousPlannedDate||null,to:item.plannedDate||null,reason:'manual-edit'}];}
  if(type==='revision'&&existingId&&previousRevisionDate!==item.date){item.history=[...(item.history||[]),{at:now,action:'rescheduled',from:previousRevisionDate||null,to:item.date||null}];}
  if(type==='task') {
    if(item.status==='completed') item.completedAt=item.completedAt||now; else item.completedAt=null;
    item.history=[...(item.history||[]),{at:now,action:existingId?'edited':'created'}];
  }
  if(type==='note'&&!existingId) item.createdAt=now;
  if(type==='block'||type==='calendar') item.status=item.status||'planned';
  if(type==='goal') { item.status=item.status||'active'; item.targetHistory=[...(item.targetHistory||[]),{at:now,previous:previousTarget,targetValue:item.targetValue,horizon:item.horizon,unit:item.unit}]; }
  if(type==='topic') { item.milestones=item.milestones||{};item.criteria=item.criteria||['theory','examples','practice','revision']; item.status=item.status||'Not Started'; }
  auditEntity(existingId?'updated':'created',type,item,before?`Updated ${item.title||item.name||''}`:`Created ${item.title||item.name||''}`);
  await persist(existingId?'Changes saved.':'Added successfully.'); $('#entityDialog').close(); pendingSubmit=null; render();
}

async function confirmAction(title,message,actionLabel,callback) {
  const dialog=$('#confirmDialog'); $('#confirmTitle').textContent=title; $('#confirmMessage').textContent=message; $('#confirmAccept').textContent=actionLabel;
  dialog.showModal(); const result=await new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue),{once:true});});
  if(result==='confirm') await callback();
}
function download(filename, content, type='application/octet-stream') { const blob=new Blob([content],{type}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=filename; document.body.append(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),1000); }
function csvEscape(value) { const text=String(value??''); return /[",\n\r]/.test(text)?`"${text.replaceAll('"','""')}"`:text; }
function exportCSV() {
  const tables={tasks:state.tasks,sessions:state.sessions,goals:state.goals,attempts:state.attempts,tests:state.tests,revisions:state.revisions};
  const out=['# Orbit JEE Student OS CSV export',`# Exported ${new Date().toISOString()}`];
  for(const [name,rows] of Object.entries(tables)) {out.push('',`[${name}]`);const keys=[...new Set(rows.flatMap(x=>Object.keys(x)))];if(!keys.length){out.push('(no records)');continue;}out.push(keys.map(csvEscape).join(','));for(const row of rows)out.push(keys.map(k=>csvEscape(typeof row[k]==='object'?JSON.stringify(row[k]):row[k])).join(','));}
  download(`orbit-report-${todayISO()}.csv`,out.join('\r\n'),'text/csv;charset=utf-8'); toast('CSV report exported.');
}
function exportBackup() { StorageService.backup().then(data=>download(`orbit-jee-backup-${todayISO()}.json`,JSON.stringify(data,null,2),'application/json')).then(()=>toast('JSON backup exported.')).catch(e=>toast(e.message,'error')); }
function exportNote(note) { download(`${(note.title||'orbit-note').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'orbit-note'}.md`,`# ${note.title}\n\n> Type: ${note.type||'Note'}\n> Updated: ${note.updatedAt||note.createdAt||''}\n\n${note.content||''}\n`,'text/markdown;charset=utf-8'); }

async function beginImport() {
  const input=document.createElement('input'); input.type='file'; input.accept='.json,application/json'; input.setAttribute('aria-label','Choose Orbit backup JSON');
  input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;if(file.size>10*1024*1024){toast('Backup exceeds the 10 MB import limit.','error');return;}try{const parsed=JSON.parse(await file.text());const mode=await new Promise(resolve=>{const useMerge=confirm('Import mode: OK = merge new records (keep current records), Cancel = replace workspace. A recovery snapshot will be saved first.');resolve(useMerge?'merge':'replace');});await confirmAction('Import backup?',`Import ${file.name} (${Math.round(file.size/1024)} KB) using ${mode} mode? Existing records will be backed up first.`, 'Import backup',async()=>{state=await StorageService.importBackup(parsed,mode);render();toast('Backup imported successfully.');});}catch(e){toast(`Import failed: ${e.message}`,'error');}}, {once:true}); input.click();
}

function edit(type,idValue) { const map={task:'tasks',subject:'subjects',chapter:'chapters',topic:'topics',goal:'goals',block:'calendarEvents',module:'modules',note:'notes',revision:'revisions',test:'tests',calendar:'calendarEvents'}; const item=find(state[map[type]],idValue); if(item) showForm(type,item); }
async function deleteItem(listName,idValue,label,linkedMessage='') {
  const item=find(state[listName],idValue); if(!item)return;
  await confirmAction(`Delete ${label}?`,`${item.title||item.name||label} will be removed. ${linkedMessage} This cannot be undone except by restoring a backup.`, 'Delete',async()=>{state[listName]=state[listName].filter(x=>x.id!==idValue);logEvent('deleted',label,idValue,item.title||item.name||'');await persist(`${label} deleted.`);render();});
}
async function toggleTask(idValue) { const t=find(state.tasks,idValue);if(!t)return;const done=t.status==='completed';t.status=done?'todo':'completed';t.completedAt=done?null:new Date().toISOString();t.updatedAt=new Date().toISOString();t.history=[...(t.history||[]),{at:t.updatedAt,action:done?'reopened':'completed'}];auditEntity(done?'reopened':'completed','task',t);await persist(done?'Task reopened.':'Task completed.');render(); }
async function changeTaskStatus(idValue) { const t=find(state.tasks,idValue);if(!t)return;const choices=[['todo','To do'],['partial','Partially complete'],['blocked','Blocked'],['completed','Completed']];const answer=prompt(`Status for “${t.title}”\n${choices.map(([v,l])=>`${v} — ${l}`).join('\n')}\n\nEnter a status:` ,t.status);if(!answer)return;const status=choices.find(x=>x[0]===answer.toLowerCase()||x[1].toLowerCase()===answer.toLowerCase())?.[0];if(!status){toast('Unknown status. Use todo, partial, blocked, or completed.','error');return;}t.status=status;t.completedAt=status==='completed'?new Date().toISOString():null;t.updatedAt=new Date().toISOString();t.history=[...(t.history||[]),{at:t.updatedAt,action:`status:${status}`}];await persist('Task status updated.');render(); }

function startSession() {
  if(state.activeSession?.status==='running'){toast('A study session is already running.','error');return;}
  showForm('session-start',{});
}
function showSessionForm() {
  if(state.activeSession){if(state.activeSession.status==='running'){toast('A study session is already running.');return;}const resume=confirm(`Resume the paused session “${state.activeSession.title}”? Choose Cancel to keep it paused.`);if(resume){state.activeSession.status='running';state.activeSession.lastTickAt=Date.now();startTimerTick();persist('Paused session resumed.').then(render).catch(e=>toast(e.message,'error'));}else toast('The existing session remains paused. Finish or cancel it before starting another.');return;}
  const fields=`${textField('title','Session focus','Study session','e.g. Kinematics — PYQs',true)}<div class="form-grid">${selectField('subjectId','Subject',state.subjects)}${selectField('chapterId','Chapter',state.chapters)}${selectField('topicId','Topic',state.topics)}${selectField('taskId','Linked task',state.tasks.filter(t=>t.status!=='completed').map(t=>({id:t.id,name:t.title})))}</div>${numberField('plannedMinutes','Planned minutes',45)}${field('activityType','Activity type',`<select name="activityType">${state.activityTypes.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`)}<p class="form-hint">If you refresh or close the page, the running timer is safely paused when you return. Time while the page is closed is not counted.</p>`;
  pendingSubmit={type:'session-start',id:null,original:{}};$('#dialogTitle').textContent='Start a study session';$('#dialogEyebrow').textContent='FOCUS TIMER';$('#dialogSubmit').textContent='Start timer';$('#dialogFields').innerHTML=fields;$('#entityDialog').showModal();
}
function sessionTimerMarkup() { const s=state.activeSession;if(!s)return '';return `<section class="timer-banner"><div><div class="eyebrow">${s.status==='running'?'SESSION IN PROGRESS':'SESSION PAUSED'}</div><h2>${esc(s.title)}</h2><p>${esc(linkLine(s.subjectId,s.chapterId,s.topicId))} · ${esc(s.activityType||'Study')}</p></div><strong id="timerDisplay">${fmtTime(s.elapsedSeconds||0)}</strong><div class="timer-actions">${button(s.status==='running'?'pause-session':'resume-session',s.status==='running'?'Ⅱ Pause':'▶ Resume','secondary-button')}${button('finish-session','Finish session','primary-button')}${button('cancel-session','Cancel','text-button')}</div></section>`;}
async function finishSession() {
  const s=state.activeSession;if(!s)return;const minutes=Math.max(0,Math.round((s.elapsedSeconds||0)/60));
  const formFields=`<p class="muted">${esc(s.title)} · ${fmtMinutes(minutes)} recorded while this page was open.</p>${numberField('actualMinutes','Actual study minutes',minutes,0)}${numberField('questionsAttempted','Questions attempted',0)}${numberField('correct','Correct',0)}${numberField('incorrect','Incorrect',0)}${textareaField('summary','Session summary / remaining doubts','','What did you cover? What remains unclear?',3)}`;
  pendingSubmit={type:'session-finish',id:s.id,original:{}};$('#dialogTitle').textContent='Finish study session';$('#dialogEyebrow').textContent='SESSION SUMMARY';$('#dialogSubmit').textContent='Save session';$('#dialogFields').innerHTML=formFields;$('#entityDialog').showModal();
}
function addStudySession(data) { const now=new Date().toISOString(); const s={...data,id:id('session'),date:todayISO(),startedAt:now,endedAt:now,actualMinutes:Number(data.actualMinutes)||0,createdAt:now};state.sessions.push(s);logEvent('logged-study-session','session',s.id,`${s.actualMinutes} minutes · ${s.title}`); }
function handleQuickAdd() {
  const options=[['task','Study task'],['session','Study session'],['subject','Subject'],['topic','Topic'],['note','Note'],['module','Practice module'],['test','Test / mock'],['revision','Revision']];
  const choice=prompt(`Quick add — type a number:\n${options.map(([k,l],i)=>`${i+1}. ${l}`).join('\n')}`,'1'); if(!choice)return; const item=options[Number(choice)-1];if(!item){toast('Choose a listed number.','error');return;}if(item[0]==='session')showSessionForm();else showForm(item[0]);
}

async function onAction(el) {
  const a=el.dataset.action, key=el.dataset.id;
  switch(a) {
    case 'quick-add':handleQuickAdd();break;case 'close-dialog':$('#entityDialog').close();pendingSubmit=null;break;
    case 'add-task':showForm('task',{},el.dataset.date?{plannedDate:el.dataset.date}:{});break;case 'edit-task':edit('task',key);break;case 'toggle-task':await toggleTask(key);break;case 'task-status':await changeTaskStatus(key);break;case 'delete-task':await deleteItem('tasks',key,'task');break;case 'clear-done':await confirmAction('Clear completed tasks?','Completed tasks will be deleted. Export a backup first if you need the history.','Clear tasks',async()=>{state.tasks=state.tasks.filter(t=>t.status!=='completed');await persist('Completed tasks cleared.');render();});break;
    case 'filter-tasks':taskFilter=el.dataset.filter;render();break;case 'view-tasks':location.hash='#tasks';break;
    case 'add-subject':showForm('subject');break;case 'edit-subject':edit('subject',key);break;case 'archive-subject':{const s=find(state.subjects,key);if(s){s.archived=true;s.archivedAt=new Date().toISOString();logEvent('archived','subject',key,s.name);await persist('Subject archived. Linked history is preserved.');render();}}break;case 'add-chapter':showForm('chapter',{},el.dataset.subject?{subjectId:el.dataset.subject}:{});break;case 'edit-chapter':edit('chapter',key);break;case 'archive-chapter':{const c=find(state.chapters,key);if(c){c.archived=true;c.archivedAt=new Date().toISOString();logEvent('archived','chapter',key,c.name);await persist('Chapter archived.');render();}}break;
    case 'add-topic':showForm('topic',{},el.dataset.chapter?{chapterId:el.dataset.chapter,subjectId:find(state.chapters,el.dataset.chapter)?.subjectId}:{});break;case 'edit-topic':edit('topic',key);break;case 'archive-topic':{const t=find(state.topics,key);if(t){t.archived=true;t.archivedAt=new Date().toISOString();logEvent('archived','topic',key,t.name);await persist('Topic archived.');render();}}break;case 'topic-detail':{const t=find(state.topics,key);if(t)showForm('topic',t);break;}case 'view-subject-chapters':syllabusTab='chapters';render();break;case 'syllabus-tab':syllabusTab=el.dataset.tab;render();break;
    case 'save-milestones':{const t=find(state.topics,key);const details=el.closest('details');if(!t||!details)break;t.milestones=t.milestones||{};for(const input of $$('input[type=checkbox]',details))if(input.name.startsWith('milestone-'))t.milestones[input.name.slice(10)]=input.checked;const p=topicProgress(t);if(p.percent===100&&t.status==='Not Started')t.status='Practiced';if(p.percent!==100&&t.status==='Completed')t.status='In Progress';t.updatedAt=new Date().toISOString();auditEntity('updated-milestones','topic',t,`${p.done}/${p.total} milestones checked`);await persist('Topic milestones saved.');render();break;}
    case 'add-goal':showForm('goal',{},el.dataset.horizon?{horizon:el.dataset.horizon}:{});break;case 'edit-goal':edit('goal',key);break;case 'archive-goal':{const g=find(state.goals,key);if(g){g.status='archived';g.archivedAt=new Date().toISOString();auditEntity('archived','goal',g);await persist('Target archived.');render();}}break;case 'add-task-to-goal':{const g=find(state.goals,key);showForm('task',{},g?{goalId:g.id,subjectId:g.subjectId,plannedDate:g.startDate||todayISO(),targetHorizon:g.horizon}:{});break;}
    case 'add-block':showForm('block',{}, {date:calendarDate||todayISO()});break;case 'edit-block':edit('block',key);break;case 'delete-block':if(el.dataset.kind==='task')await deleteItem('tasks',key,'task');else await deleteItem('calendarEvents',key,'calendar item');break;case 'complete-block':{const b=find(state.calendarEvents,key);if(b){b.status=b.status==='completed'?'planned':'completed';await persist('Study block updated.');render();}}break;
    case 'prev-day':calendarDate=shiftDate(calendarDate,-1);render();break;case 'next-day':calendarDate=shiftDate(calendarDate,1);render();break;case 'today-planner':calendarDate=todayISO();render();break;
    case 'week-prev':calendarDate=shiftDate(calendarDate,-7);render();break;case 'week-next':calendarDate=shiftDate(calendarDate,7);render();break;case 'month-prev':calendarDate=`${new Date(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7))-2,1,12).getFullYear()}-${String(new Date(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7))-2,1,12).getMonth()+1).padStart(2,'0')}-01`;render();break;case 'month-next':calendarDate=`${new Date(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7)),1,12).getFullYear()}-${String(new Date(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7)),1,12).getMonth()+1).padStart(2,'0')}-01`;render();break;case 'open-week':calendarDate=el.dataset.date;currentView='weekly';location.hash='#weekly';render();break;case 'spread-week-tasks':{const start=weekStartISO(calendarDate),dates=Array.from({length:7},(_,i)=>shiftDate(start,i)).filter(d=>d>=todayISO());if(!dates.length){toast('There are no remaining days in the selected week. Choose the current or a future week.','error');break;}const unfinished=state.tasks.filter(t=>t.status!=='completed'&&t.status!=='cancelled'&&(t.plannedDate||t.dueDate)>=start&&(t.plannedDate||t.dueDate)<=shiftDate(start,6));if(!unfinished.length){toast('No unfinished tasks in this week.');break;}await confirmAction('Redistribute unfinished tasks?',`${unfinished.length} unfinished task(s) will be spread across ${dates.length} remaining day(s). Previous dates are kept in each task history.`, 'Redistribute',async()=>{unfinished.forEach((t,i)=>{const old=t.plannedDate;t.plannedDate=dates[i%Math.max(1,dates.length)];t.updatedAt=new Date().toISOString();t.history=[...(t.history||[]),{at:t.updatedAt,action:'rescheduled',from:old||null,to:t.plannedDate,reason:'weekly-redistribution'}];});logEvent('redistributed-weekly-tasks','task',null,`${unfinished.length} tasks redistributed`);await persist('Tasks redistributed.');render();});break;}
    case 'add-module':showForm('module');break;case 'edit-module':edit('module',key);break;case 'delete-module':await deleteItem('modules',key,'practice module','Recorded attempts linked to it will remain in the overall attempt history.');break;case 'add-attempt':showForm('attempt',{}, {moduleId:key,subjectId:find(state.modules,key)?.subjectId,chapterId:find(state.modules,key)?.chapterId,topicId:find(state.modules,key)?.topicId});break;case 'module-history':{const m=find(state.modules,key);const list=getAttempts(key);alert(`${m?.name||'Module'}\n\n${list.map(a=>`${a.at?.slice(0,10)||''} · ${a.outcome} · ${a.questionRef||'No question ID'}${a.solutionNotes?`\n${a.solutionNotes}`:''}`).join('\n\n')||'No attempts recorded yet.'}`);break;}
    case 'add-note':showForm('note');break;case 'edit-note':edit('note',key);break;case 'pin-note':{const n=find(state.notes,key);if(n){n.pinned=!n.pinned;n.updatedAt=new Date().toISOString();await persist(n.pinned?'Note pinned.':'Note unpinned.');render();}}break;case 'export-note':{const n=find(state.notes,key);if(n)exportNote(n);break;}case 'export-notes-all':{const content=state.notes.filter(n=>!n.archived).map(n=>`# ${n.title}\n\n> ${n.type||'Note'} · ${subjectName(n.subjectId)}\n\n${n.content||''}\n`).join('\n---\n\n');download(`orbit-notes-${todayISO()}.md`,content,'text/markdown;charset=utf-8');toast('Notes exported as Markdown.');break;}
    case 'add-revision':showForm('revision');break;case 'edit-revision':edit('revision',key);break;case 'delete-revision':await deleteItem('revisions',key,'revision item');break;case 'complete-revision':{const r=find(state.revisions,key);if(r){r.completedAt=new Date().toISOString();r.lastRecall=prompt('How well could you recall this? Enter: strong, partial, or weak','partial')||'unrated';state.revisionEvents.push({id:id('revision-event'),revisionId:r.id,topicId:r.topicId,at:r.completedAt,recall:r.lastRecall});if(r.topicId){const t=find(state.topics,r.topicId);if(t&&r.lastRecall==='weak')t.status='Needs Improvement';}await persist('Revision recorded.');render();}}break;
    case 'add-test':showForm('test');break;case 'edit-test':edit('test',key);break;case 'delete-test':await deleteItem('tests',key,'test record');break;
    case 'add-calendar-event':showForm('calendar',{}, {date:calendarDate});break;case 'calendar-prev':calendarDate=`${new Date(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7))-2,1,12).getFullYear()}-${String(new Date(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7))-2,1,12).getMonth()+1).padStart(2,'0')}-01`;render();break;case 'calendar-next':calendarDate=`${new Date(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7)),1,12).getFullYear()}-${String(new Date(Number(calendarDate.slice(0,4)),Number(calendarDate.slice(5,7)),1,12).getMonth()+1).padStart(2,'0')}-01`;render();break;case 'calendar-today':calendarDate=todayISO();render();break;case 'select-calendar-date':calendarDate=el.dataset.date;render();break;
    case 'export-backup':exportBackup();break;case 'export-report-csv':exportCSV();break;case 'import-backup':beginImport();break;case 'restore-recovery':await confirmAction('Restore the pre-import snapshot?','This replaces the current workspace with the last saved recovery snapshot. Export your current state first if you need it.','Restore snapshot',async()=>{state=await StorageService.restoreLatestRecovery();await persist('Recovery snapshot restored.');render();});break;
    case 'set-theme':state.settings.theme=el.dataset.theme;await persist();render();break;case 'clear-data':await confirmAction('Clear all local data?','This permanently removes the active workspace, the legacy Orbit task list, and migration backups from this browser. Export a JSON backup first. This cannot be undone here.','Clear workspace',async()=>{const blank={version:3,profile:{...state.profile,setupComplete:false},settings:{...state.settings},subjects:[],chapters:[],topics:[],goals:[],tasks:[],sessions:[],modules:[],attempts:[],notes:[],revisions:[],revisionEvents:[],tests:[],calendarEvents:[],activityTypes:[...ACTIVITY_TYPES],audit:[],activeSession:null,migratedLegacy:false};await StorageService.clearAll(blank);state=blank;toast('Local workspace cleared.');currentView='dashboard';location.hash='#dashboard';render();});break;
    case 'save-settings':{const form=$('#settingsForm');const d=formValues(form);state.profile.displayName=d.displayName;state.profile.studyLevel=d.studyLevel;state.profile.examTarget=d.examTarget;state.profile.targetExamDate=d.targetExamDate;state.profile.availableHours=d.availableHours;state.settings.dayStart=d.dayStart;state.settings.dayEnd=d.dayEnd;await persist('Preferences saved.');render();break;}
    case 'onboarding':showOnboarding();break;case 'start-session':showSessionForm();break;case 'pause-session':if(state.activeSession?.status==='running'){state.activeSession.status='paused';state.activeSession.pausedAt=new Date().toISOString();clearInterval(timerHandle);timerHandle=null;await persist('Session paused.');render();}break;case 'resume-session':if(state.activeSession?.status==='paused'){state.activeSession.status='running';state.activeSession.lastTickAt=Date.now();startTimerTick();await persist('Session resumed.');render();}break;case 'finish-session':finishSession();break;case 'cancel-session':await confirmAction('Cancel this session?','The current timer will be discarded; no study session will be logged.','Cancel session',async()=>{state.activeSession=null;clearInterval(timerHandle);await persist('Session cancelled.');render();});break;
    default:break;
  }
}

function showOnboarding() {
  const fields=`${textField('displayName','Name (optional)',state.profile.displayName,'Your name')}${field('studyLevel','Study level',`<select name="studyLevel">${['Class 11','Class 12','Drop year','Other'].map(x=>`<option ${state.profile.studyLevel===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('examTarget','Exam focus',`<select name="examTarget">${['JEE Main','JEE Advanced','JEE Main + Advanced','Other'].map(x=>`<option ${state.profile.examTarget===x?'selected':''}>${x}</option>`).join('')}</select>`)}${numberField('availableHours','Available study hours per day',state.profile.availableHours||6,0,24)}<p class="form-hint">You can add or remove subjects later. Setup creates subject shells only — no fake syllabus or progress.</p>${SUBJECT_PRESETS.map(s=>checkField(`preset-${s.name}`,`Add ${s.name}`,!state.subjects.some(x=>x.name===s.name))).join('')}`;
  pendingSubmit={type:'onboarding',id:null,original:{}};$('#dialogTitle').textContent='Set up your study workspace';$('#dialogEyebrow').textContent='WELCOME TO ORBIT';$('#dialogSubmit').textContent='Save setup';$('#dialogFields').innerHTML=fields;$('#entityDialog').showModal();
}

function startTimerTick() {
  clearInterval(timerHandle); if(state.activeSession?.status!=='running')return;
  state.activeSession.lastTickAt=Date.now();
  timerHandle=setInterval(()=>{const s=state.activeSession;if(!s||s.status!=='running'){clearInterval(timerHandle);timerHandle=null;return;}const now=Date.now();s.elapsedSeconds=(s.elapsedSeconds||0)+Math.max(0,(now-(s.lastTickAt||now))/1000);s.lastTickAt=now;const display=$('#timerDisplay');if(display)display.textContent=fmtTime(s.elapsedSeconds);if(Math.round(s.elapsedSeconds)%15===0)StorageService.save(state).catch(()=>{});},1000);
}

async function submitDialog(event) {
  event.preventDefault(); if(!pendingSubmit)return;
  const type=pendingSubmit.type;
  if(type==='session-start') {const d=formValues($('#entityForm'));state.activeSession={...d,id:id('active-session'),startedAt:new Date().toISOString(),date:todayISO(),elapsedSeconds:0,status:'running',lastTickAt:Date.now()};logEvent('started-study-session','session',state.activeSession.id,state.activeSession.title);await persist('Study timer started.');$('#entityDialog').close();pendingSubmit=null;startTimerTick();render();return;}
  if(type==='session-finish') {const d=formValues($('#entityForm'));const active=state.activeSession;if(!active)return;const item={...active,...d,id:id('session'),endedAt:new Date().toISOString(),date:active.date,actualMinutes:Math.max(0,Number(d.actualMinutes)||0),createdAt:new Date().toISOString()};delete item.status;delete item.lastTickAt;delete item.pausedAt;state.sessions.push(item);if(item.questionsAttempted>0&&Number(item.correct||0)+Number(item.incorrect||0)>Number(item.questionsAttempted)){toast('Correct + incorrect cannot exceed attempted questions. Session was not saved; please correct the summary.','error');state.sessions=state.sessions.filter(x=>x.id!==item.id);state.activeSession=active;return;}if(item.questionsAttempted>0){for(let i=0;i<item.questionsAttempted;i++){state.attempts.push({id:id('attempt'),sessionId:item.id,subjectId:item.subjectId,chapterId:item.chapterId,topicId:item.topicId,at:item.endedAt,outcome:i<item.correct?'correct':i<item.correct+item.incorrect?'incorrect':'unresolved'});}}if(item.taskId){const task=find(state.tasks,item.taskId);if(task){task.actualMinutes=(task.actualMinutes||0)+item.actualMinutes;task.completedQuestions=(task.completedQuestions||0)+(item.questionsAttempted||0);task.correct=(task.correct||0)+(item.correct||0);task.incorrect=(task.incorrect||0)+(item.incorrect||0);}}state.activeSession=null;clearInterval(timerHandle);timerHandle=null;logEvent('finished-study-session','session',item.id,`${item.actualMinutes} minutes · ${item.title}`);await persist('Study session saved.');$('#entityDialog').close();pendingSubmit=null;render();return;}
  if(type==='onboarding') {const d=formValues($('#entityForm'));state.profile.displayName=d.displayName;state.profile.studyLevel=d.studyLevel;state.profile.examTarget=d.examTarget;state.profile.availableHours=d.availableHours;state.profile.setupComplete=true;for(const s of SUBJECT_PRESETS)if(d[`preset-${s.name}`]&&!state.subjects.some(x=>x.name===s.name))state.subjects.push({id:id('subject'),...s,level:d.studyLevel,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),targetHours:0,archived:false});logEvent('completed-onboarding','profile',null,'Academic setup saved.');await persist('Workspace setup complete.');$('#entityDialog').close();pendingSubmit=null;render();return;}
  await submitEntity($('#entityForm'));
}

function installEvents() {
  document.addEventListener('click',event=>{const action=event.target.closest('[data-action]');if(action){event.preventDefault();onAction(action).catch(e=>toast(e.message||'Action failed.','error'));return;}const nav=event.target.closest('[data-view]');if(nav){event.preventDefault();currentView=nav.dataset.view;location.hash=`#${currentView}`;closeMobileNav();render();}});
  $('#entityForm').addEventListener('submit',submitDialog);
  $('#themeBtn').addEventListener('click',async()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';await persist();render();});
  $('#menuBtn').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('#menuBtn').setAttribute('aria-expanded',String(open));});
  $('#sidebarScrim').addEventListener('click',closeMobileNav);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileNav();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();handleQuickAdd();}});
  $('#entityDialog').addEventListener('close',()=>{pendingSubmit=null;});
  $('#appView').addEventListener('change',async e=>{if(e.target.id==='reducedMotion'){state.settings.reduceMotion=e.target.checked;await persist('Accessibility preference saved.');render();}});
  $('#appView').addEventListener('submit',async e=>{if(e.target.id==='settingsForm'){e.preventDefault();await onAction({dataset:{action:'save-settings'}});}});
  window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(VIEW_NAMES[v]){currentView=v;closeMobileNav();render();}});
  window.addEventListener('pagehide',()=>{if(state?.activeSession?.status==='running'){state.activeSession.status='paused';state.activeSession.pausedAt=new Date().toISOString();clearInterval(timerHandle);StorageService.save(state).catch(()=>{});}});
}
function closeMobileNav(){document.body.classList.remove('nav-open');$('#menuBtn').setAttribute('aria-expanded','false');}

async function boot() {
  try { state=await StorageService.load(); }
  catch(error) { state=await StorageService.load().catch(()=>null);if(!state){$('#appView').innerHTML=`<section class="panel"><h1>Orbit could not open its saved workspace</h1><p>${esc(error.message)}</p><p>Your previous data was not intentionally deleted. Check browser storage availability, then reload.</p></section>`;return;} }
  if(state.activeSession?.status==='running'){state.activeSession.status='paused';state.activeSession.pausedAt=new Date().toISOString();state.activeSession.recoveredAfterReload=true;await StorageService.save(state).catch(()=>{});}
  if(!state.settings.theme)state.settings.theme='dark';
  installEvents();render();
}
boot();
